export class CulturalQuizEngine{constructor(e={}){this.currentCategory=e.category||"general",this.score=0,this.streak=0,this.unlockedBadges=new Set(e.initialBadges||[]),this.questionIndex=0,this.badges={HERITAGE_EXPLORER:{id:"HERITAGE_EXPLORER",name:"Heritage Explorer",minScore:50},CULTURE_MAESTRO:{id:"CULTURE_MAESTRO",name:"Culture Maestro",minScore:100},STREAK_CHAMPION:{id:"STREAK_CHAMPION",name:"Streak Champion",minStreak:5}}}submitAnswer(e,s=10){if(e){this.streak+=1;const e=this.streak>=3?1.5:1;return this.score+=Math.round(s*e),this.checkBadgeEligibility(),{correct:!0,addedPoints:Math.round(s*e),streak:this.streak}}return this.streak=0,{correct:!1,addedPoints:0,streak:0}}checkBadgeEligibility(){const e=[];return this.score>=50&&!this.unlockedBadges.has("HERITAGE_EXPLORER")&&(this.unlockedBadges.add("HERITAGE_EXPLORER"),e.push(this.badges.HERITAGE_EXPLORER)),this.score>=100&&!this.unlockedBadges.has("CULTURE_MAESTRO")&&(this.unlockedBadges.add("CULTURE_MAESTRO"),e.push(this.badges.CULTURE_MAESTRO)),this.streak>=5&&!this.unlockedBadges.has("STREAK_CHAMPION")&&(this.unlockedBadges.add("STREAK_CHAMPION"),e.push(this.badges.STREAK_CHAMPION)),e}resetQuiz(){this.score=0,this.streak=0,this.questionIndex=0}serializeState(){return JSON.stringify({score:this.score,streak:this.streak,unlockedBadges:Array.from(this.unlockedBadges)})}}